contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        uint256 balBefore = address(this).balance;
        uint256 userBefore = c.getBalance(address(this));

        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 userAfter = c.getBalance(address(this));
        uint256 balAfter = address(this).balance;

        assert(
            !reverted &&
            userBefore == 0 &&
            userAfter == 0 &&
            balAfter == balBefore
        );
    }

    receive() external payable {}
}

