    constructor(C _c) {
        c = _c;
    }

    function run(uint initialAmount, uint extraAmount) public payable {
        require(address(this).balance >= initialAmount + extraAmount);

        // give the caller a recorded balance
        c.addToBalance{value: initialAmount}();
        uint b0 = c.getBalance(address(this));

        // withdraw everything
        uint cBalBefore = address(c).balance;
        c.withdrawBalance();
