contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        c.addToBalance{value: amount}();

        uint recordedBefore = c.getBalance(address(this));
        uint contractBalanceBefore = address(c).balance;

        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (contractBalanceBefore < recordedBefore) {
            assert(reverted && c.getBalance(address(this)) == recordedBefore && address(c).balance == contractBalanceBefore);
        } else {
            assert(!reverted && c.getBalance(address(this)) == 0 && address(c).balance == contractBalanceBefore - recordedBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 a) public payable {
        require(address(this).balance >= a);

        uint256 beforeTest = address(this).balance;
        uint256 beforeC = address(c).balance;

        c.addToBalance{value: a}();
        uint256 recordedBefore = c.getBalance(address(this));
        uint256 cBeforeWithdraw = address(c).balance;

        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTest = address(this).balance;
        uint256 afterC = address(c).balance;
        uint256 recordedAfter = c.getBalance(address(this));

        assert(recordedBefore == a && cBeforeWithdraw == beforeC + a &&
               (reverted ? (afterTest == beforeTest && afterC == cBeforeWithdraw && recordedAfter == recordedBefore)
                         : (afterTest == beforeTest + recordedBefore && afterC == cBeforeWithdraw - recordedBefore && recordedAfter == 0)));
    }

    receive() external payable {}
}

